const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (typeof $json.tender_id !== 'string' || !uuid.test($json.tender_id) || typeof $json.org_id !== 'string' || !uuid.test($json.org_id)) {
  throw new Error('INVALID_TENANT_CONTEXT');
}
return [{ json: $json }];

const tender = $('load-requirements').first().json;
const profile = $('load-company-profile').first().json || {};
const rawProjectReferences = Array.isArray(profile.project_references) ? profile.project_references : [];
const projectReferences = rawProjectReferences.filter((reference) =>
  reference && typeof reference === 'object' &&
  typeof reference.client === 'string' && reference.client.trim().length > 0 &&
  typeof reference.project === 'string' && reference.project.trim().length > 0);
const projectReferencesState = projectReferences.length > 0
  ? 'provided'
  : profile.project_references_state === 'explicitly_absent'
    ? 'explicitly_absent'
    : 'not_provided';

// Build company profile object for LLM
const companyProfile = {
  name: profile.company_name || profile.name || 'Unbekanntes Unternehmen',
  capabilities_summary: profile.capabilities_summary || '',
  certifications: profile.certifications || [],
  trades: profile.trades || [],
  regions: profile.regions || [],
  service_types: profile.service_types || [],
  project_references: projectReferences,
  project_references_state: projectReferencesState,
  // HQ address for distance calculation (IMP-03b)
  hq_street:      profile.hq_street      || null,
  hq_postal_code: profile.hq_postal_code || null,
  hq_city:        profile.hq_city        || null,
};

const requirements = tender.requirements || [];
const referenceTerms = [
  'referenzprojekt', 'referenzobjekt', 'referenzleistung', 'referenznachweis',
  'vergleichbare projekte', 'vergleichbaren projekten', 'vergleichbare leistungen',
];
const referenceRequirementIds = requirements.filter((requirement) => {
  const text = [requirement?.title, requirement?.description]
    .filter((value) => typeof value === 'string')
    .join(' ')
    .toLocaleLowerCase('de-DE');
  return referenceTerms.some((term) => text.includes(term));
}).map((requirement) => requirement.id);
const referenceEvidenceUnknownIds = projectReferencesState === 'not_provided'
  ? referenceRequirementIds : [];
const referenceEvidenceAbsentIds = projectReferencesState === 'explicitly_absent'
  ? referenceRequirementIds : [];

// Bauort context for distance/travel risk assessment
const bauort = tender.region || null;

// Wertschöpfungsanalyse — from stage 2 classification
const vb = tender.value_breakdown || null;
const valueBreakdownNote = vb ? (function() {
  const s = vb.summary || {};
  const total = s.total || 1;
  const fremdPct = Math.round((s.fremd || 0) / total * 100);
  const lieferPct = Math.round((s.liefer || 0) / total * 100);
  const gemischtPct = Math.round((s.gemischt || 0) / total * 100);
  const eigenPct = 100 - fremdPct - lieferPct - gemischtPct;
  const parts = [];
  if (eigenPct > 0)    parts.push(eigenPct + '% Eigenleistung (' + s.eigen + ' Pos.)');
  if (fremdPct > 0)    parts.push(fremdPct + '% Fremdleistung (' + s.fremd + ' Pos.)');
  if (lieferPct > 0)   parts.push(lieferPct + '% Lieferleistung (' + s.liefer + ' Pos.)');
  if (gemischtPct > 0) parts.push(gemischtPct + '% Mischleistung (' + s.gemischt + ' Pos.)');
  return parts.join(', ');
})() : null;
const companyRegions = profile.regions || [];
// Simple heuristic: flag if Bauort is not within any of the company's listed regions
// e.g. company covers 'Bayern', Bauort is 'Nordrhein-Westfalen' → outside service area
const bauortOutsideRegions = bauort && companyRegions.length > 0
  ? !companyRegions.some(r => bauort.toLowerCase().includes(r.toLowerCase()) || r.toLowerCase().includes(bauort.toLowerCase()))
  : false;

return [{ json: {
  tender_id: tender.id,
  company_profile: companyProfile,
  requirements,
  requirements_json: JSON.stringify(requirements),
  reference_evidence_unknown_ids: referenceEvidenceUnknownIds,
  reference_evidence_absent_ids: referenceEvidenceAbsentIds,
  bauort,
  bauort_outside_regions: bauortOutsideRegions,
  company_regions_str: companyRegions.join(', ') || 'nicht angegeben',
  value_breakdown_note: valueBreakdownNote,
} }];

// ─── Distance calculation node ───────────────────────────────────────────────
// Provider-agnostic distance calculation between company HQ and Bauort.
// To swap provider: replace the `geocode()` function body only.
// Current provider: Nominatim (OpenStreetMap) — free, no API key required.
//
// Returns distance_km (straight-line Haversine) + geocode metadata.
// Fails gracefully: if geocoding fails, distance_km = null and evaluation continues.

const ctx = $json;

// ─── Provider: Nominatim ─────────────────────────────────────────────────────
// To use OpenRouteService: replace URL + parse response accordingly.
// To use Google Maps: replace with Distance Matrix API call.
async function geocode(query) {
  const url = 'https://nominatim.openstreetmap.org/search?format=json&limit=1&q=' +
    encodeURIComponent(query);
  const resp = await fetch(url, {
    headers: { 'User-Agent': 'Tenderly/1.0 (tender-analysis)' },
    signal: AbortSignal.timeout(8000),
  });
  if (!resp.ok) throw new Error(`Nominatim HTTP ${resp.status}`);
  const data = await resp.json();
  if (!data || !data.length) return null;
  return { lat: parseFloat(data[0].lat), lon: parseFloat(data[0].lon), display: data[0].display_name };
}

// ─── Haversine formula ────────────────────────────────────────────────────────
// Straight-line distance in km. Used only to derive an explicitly labelled display estimate.
// Typical road distance is ~1.2–1.4x straight-line for Central Europe.
function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2)**2 +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon/2)**2;
  return R * 2 * Math.asin(Math.sqrt(a));
}

// ─── Build geocode queries ────────────────────────────────────────────────────
const profile = ctx.company_profile || {};
const hqCity   = profile.hq_city        || null;
const hqPostal = profile.hq_postal_code || null;
const hqStreet = profile.hq_street      || null;
const bauort   = ctx.bauort             || null;

// Build address strings — as specific as available, Germany assumed
const hqQuery = hqPostal && hqCity
  ? `${hqPostal} ${hqCity}, Deutschland`
  : hqCity
  ? `${hqCity}, Deutschland`
  : hqStreet && hqCity
  ? `${hqStreet}, ${hqCity}, Deutschland`
  : null;

const bauortQuery = bauort ? `${bauort}, Deutschland` : null;

// ─── Geocode both and compute distance ───────────────────────────────────────
let distanceKm   = null;
let distanceNote = null;
let hqGeo        = null;
let bauortGeo    = null;

if (hqQuery && bauortQuery) {
  try {
    [hqGeo, bauortGeo] = await Promise.all([geocode(hqQuery), geocode(bauortQuery)]);
    // German locality names in company profiles can be more specific than the postal index.
    // Fall back conservatively without weakening Bauort matching or hiding provider failures.
    if (!hqGeo && hqPostal) hqGeo = await geocode(`${hqPostal}, Deutschland`);
    if (!hqGeo && hqCity) hqGeo = await geocode(`${hqCity}, Deutschland`);
    if (hqGeo && bauortGeo) {
      distanceKm = Math.round(haversine(hqGeo.lat, hqGeo.lon, bauortGeo.lat, bauortGeo.lon));
      // Rough road-distance estimate (Haversine × 1.3 for Central Europe)
      const roadEstimate = Math.round(distanceKm * 1.3);
      distanceNote = `ca. ${roadEstimate} km Fahrtstrecke geschätzt · ${distanceKm} km Luftlinie · ${hqCity || 'Firmensitz'} → ${bauort}`;
    } else {
      distanceNote = 'Geocodierung nicht erfolgreich — Entfernung unbekannt';
    }
  } catch (e) {
    distanceNote = 'Geocodierung fehlgeschlagen: ' + String(e).slice(0, 80);
  }
} else if (!hqQuery) {
  distanceNote = 'Firmenanschrift nicht hinterlegt — Entfernung nicht berechnet';
} else {
  distanceNote = 'Bauort unbekannt — Entfernung nicht berechnet';
}

return [{ json: {
  ...ctx,
  distance_km:    distanceKm,
  distance_note:  distanceNote,
  hq_geo:         hqGeo,
  bauort_geo:     bauortGeo,
}}];

const tender = $('load-requirements').first().json;
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isBoundedString = (value, maxLength) =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maxLength;
const findings = [];
const addFinding = (path, problem, details) => findings.push({
  path,
  problem,
  ...(details === undefined ? {} : { details }),
});
const failUnsafe = () => {
  console.error('LLM_RESPONSE_INVALID_JSON');
  throw new Error('LLM_RESPONSE_INVALID_JSON');
};
const parseNested = (value, path) => {
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch {
    addFinding(path, 'must_be_valid_json_or_native_json');
    return undefined;
  }
};

let candidate;
try {
  const content = $json.choices?.[0]?.message?.content;
  candidate = typeof content === 'string'
    ? JSON.parse(content.replace(/\x60\x60\x60json|\x60\x60\x60/g, '').trim())
    : content;
} catch {
  failUnsafe();
}
if (!isObject(candidate)) failUnsafe();

const candidateKeys = [
  'strategic_fit_score',
  'rationale',
  'strengths',
  'eligibility_requirements',
  'score_drivers',
  'risks',
  'clarifications',
];
const repairCandidate = Object.fromEntries(
  candidateKeys
    .filter((key) => Object.prototype.hasOwnProperty.call(candidate, key))
    .map((key) => [key, candidate[key]]),
);
if (JSON.stringify(repairCandidate).length > 40_000) failUnsafe();

if (!Number.isInteger(candidate.strategic_fit_score)
  || candidate.strategic_fit_score < 0
  || candidate.strategic_fit_score > 100) {
  addFinding('strategic_fit_score', 'must_be_integer_0_to_100');
}
if (!isBoundedString(candidate.rationale, 5000)) {
  addFinding('rationale', 'must_be_nonempty_string_max_5000');
}

const strengths = candidate.strengths == null
  ? []
  : parseNested(candidate.strengths, 'strengths');
if (!Array.isArray(strengths)
  || strengths.length > 20
  || !strengths.every((item) => isBoundedString(item, 500))) {
  addFinding('strengths', 'must_be_array_of_up_to_20_strings_max_500');
}

const sourceRequirements = Array.isArray(tender.requirements) ? tender.requirements : [];
const sourceIds = sourceRequirements
  .map((requirement) => requirement?.id)
  .filter((id) => isBoundedString(id, 100));
const knownIds = new Set(sourceIds);
if (sourceIds.length !== sourceRequirements.length || knownIds.size !== sourceIds.length) failUnsafe();
const repairSourceRequirements = sourceRequirements.map((requirement) => ({
  id: requirement.id,
  category: requirement.category,
  title: requirement.title,
  description: requirement.description,
  is_critical: requirement.is_critical,
  is_implicit: requirement.is_implicit,
  source_fragments: requirement.source_fragments,
}));
if (JSON.stringify(repairSourceRequirements).length > 40_000) failUnsafe();

const eligibility = parseNested(candidate.eligibility_requirements, 'eligibility_requirements');
if (!Array.isArray(eligibility) || eligibility.length > 25) {
  addFinding('eligibility_requirements', 'must_be_array_with_one_item_per_source_requirement');
} else {
  const seen = new Set();
  const unknownIds = [];
  const duplicateIds = [];
  for (const [index, requirement] of eligibility.entries()) {
    const path = 'eligibility_requirements[' + index + ']';
    if (!isObject(requirement)) {
      addFinding(path, 'must_be_object');
      continue;
    }
    if (!isBoundedString(requirement.id, 100) || !knownIds.has(requirement.id)) {
      unknownIds.push(typeof requirement.id === 'string' ? requirement.id.slice(0, 100) : null);
    } else if (seen.has(requirement.id)) {
      duplicateIds.push(requirement.id);
    } else {
      seen.add(requirement.id);
    }
    if (!['compliant', 'partial', 'needs_review', 'not_met'].includes(requirement.status)) {
      addFinding(path + '.status', 'must_be_compliant_partial_needs_review_or_not_met');
    }
    if (typeof requirement.is_blocking !== 'boolean') {
      addFinding(path + '.is_blocking', 'must_be_boolean');
    }
  }
  const missingIds = sourceIds.filter((id) => !seen.has(id));
  if (eligibility.length !== sourceIds.length || unknownIds.length || duplicateIds.length || missingIds.length) {
    addFinding('eligibility_requirements', 'must_cover_source_ids_exactly_once', {
      missing_ids: missingIds,
      unknown_ids: unknownIds,
      duplicate_ids: duplicateIds,
    });
  }
}

const scoreDrivers = candidate.score_drivers == null
  ? []
  : parseNested(candidate.score_drivers, 'score_drivers');
if (!Array.isArray(scoreDrivers)
  || scoreDrivers.length > 6
  || (knownIds.size > 0 && scoreDrivers.length === 0)) {
  addFinding('score_drivers', 'must_be_array_of_1_to_6_exact_requirement_factors');
} else {
  const seen = new Set();
  const statusById = new Map(
    Array.isArray(eligibility)
      ? eligibility
        .filter((item) => isObject(item) && knownIds.has(item.id))
        .map((item) => [item.id, item.status])
      : []
  );
  const expectedDirection = (status) =>
    status === 'compliant' ? 'positive'
      : status === 'not_met' ? 'negative'
        : ['partial', 'needs_review'].includes(status) ? 'uncertain' : null;
  for (const [index, driver] of scoreDrivers.entries()) {
    const path = 'score_drivers[' + index + ']';
    if (!isObject(driver)) {
      addFinding(path, 'must_be_object');
      continue;
    }
    const knownUniqueId = isBoundedString(driver.id, 100)
      && knownIds.has(driver.id)
      && !seen.has(driver.id);
    if (!knownUniqueId) {
      addFinding(path + '.id', 'must_be_unique_exact_source_requirement_id');
    } else {
      seen.add(driver.id);
    }
    if (!['positive', 'negative', 'uncertain'].includes(driver.direction)) {
      addFinding(path + '.direction', 'must_be_positive_negative_or_uncertain');
    } else if (knownUniqueId) {
      const expected = expectedDirection(statusById.get(driver.id));
      if (expected && driver.direction !== expected) {
        addFinding(path + '.direction', 'must_match_eligibility_status');
      }
    }
    if (!isBoundedString(driver.explanation, 500)) {
      addFinding(path + '.explanation', 'must_be_nonempty_string_max_500');
    }
  }
}

const risks = candidate.risks == null ? [] : parseNested(candidate.risks, 'risks');
if (!Array.isArray(risks) || risks.length > 8) {
  addFinding('risks', 'must_be_array_of_up_to_8_items');
} else {
  const ids = new Set();
  for (const [index, risk] of risks.entries()) {
    const path = 'risks[' + index + ']';
    if (!isObject(risk)
      || !isBoundedString(risk.id, 100)
      || ids.has(risk.id)
      || !isBoundedString(risk.title, 200)
      || !isBoundedString(risk.text, 2000)
      || !['low', 'medium', 'high'].includes(risk.severity)
      || !isBoundedString(risk.mitigation, 2000)) {
      addFinding(path, 'must_match_risk_schema_with_unique_id');
    } else {
      ids.add(risk.id);
    }
  }
}

const clarifications = candidate.clarifications == null
  ? []
  : parseNested(candidate.clarifications, 'clarifications');
if (!Array.isArray(clarifications) || clarifications.length > 8) {
  addFinding('clarifications', 'must_be_array_of_up_to_8_items');
} else {
  const ids = new Set();
  for (const [index, clarification] of clarifications.entries()) {
    const path = 'clarifications[' + index + ']';
    if (!isObject(clarification)
      || !isBoundedString(clarification.id, 100)
      || ids.has(clarification.id)
      || !isBoundedString(clarification.question, 2000)
      || !['medium', 'high'].includes(clarification.priority)) {
      addFinding(path, 'must_match_clarification_schema_with_unique_id');
    } else {
      ids.add(clarification.id);
    }
  }
}

return [{ json: {
  ...$json,
  reconciliation_required: findings.length > 0,
  reconciliation_findings: findings,
  reconciliation_candidate: repairCandidate,
  reconciliation_source_requirements: repairSourceRequirements,
} }];

