const tender = $('load-requirements').first().json;
const tenderId = tender.id;
const eligibilityKeys = ['id', 'status', 'is_blocking'];
const riskKeys = ['id', 'title', 'text', 'severity', 'mitigation'];
const clarificationKeys = ['id', 'question', 'priority'];
const coverageKeys = ['source_insufficient', 'source_truncated', 'source_char_count', 'extracted_char_count', 'source_char_limit', 'requirement_count', 'requirement_limit', 'requirement_limit_reached'];
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isBoundedString = (value, maxLength) =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maxLength;
const isExactObject = (value, keys) =>
  isObject(value) && Object.keys(value).length === keys.length &&
  keys.every((key) => Object.prototype.hasOwnProperty.call(value, key));
const isNonnegativeInteger = (value) => Number.isInteger(value) && value >= 0;
const parseIfString = (value) => typeof value === 'string' ? JSON.parse(value) : value;
const hasUniqueIds = (items) => new Set(items.map((item) => item.id)).size === items.length;
const referenceEvidenceUnknownIds = new Set(
  Array.isArray($('prepare-context').first().json.reference_evidence_unknown_ids)
    ? $('prepare-context').first().json.reference_evidence_unknown_ids
    : []
);
const referenceEvidenceAbsentIds = new Set(
  Array.isArray($('prepare-context').first().json.reference_evidence_absent_ids)
    ? $('prepare-context').first().json.reference_evidence_absent_ids
    : []
);
const referenceReviewReason = 'Referenzprojekte wurden im Unternehmensprofil noch nicht hinterlegt.';
const referenceAbsentReason = 'Das Unternehmen hat ausdrücklich angegeben, dass keine Referenzprojekte vorliegen.';

let evaluation;
let actualBlockingCount = 0;
try {
  const content = $json.choices?.[0]?.message?.content;
  const rawEvaluation = typeof content === 'string'
    ? JSON.parse(content.replace(/\x60\x60\x60json|\x60\x60\x60/g, '').trim())
    : content;
  if (!isObject(rawEvaluation)) throw new Error('invalid response');

  const strengths = rawEvaluation.strengths == null ? [] : parseIfString(rawEvaluation.strengths);
  const eligibilityRequirements = parseIfString(rawEvaluation.eligibility_requirements);
  const scoreDrivers = rawEvaluation.score_drivers == null ? [] : parseIfString(rawEvaluation.score_drivers);
  const risks = rawEvaluation.risks == null ? [] : parseIfString(rawEvaluation.risks);
  const clarifications = rawEvaluation.clarifications == null ? [] : parseIfString(rawEvaluation.clarifications);
  if (
    !Number.isInteger(rawEvaluation.strategic_fit_score) ||
    rawEvaluation.strategic_fit_score < 0 ||
    rawEvaluation.strategic_fit_score > 100 ||
    !isBoundedString(rawEvaluation.rationale, 5000) ||
    !Array.isArray(strengths) ||
    strengths.length > 20 ||
    !strengths.every((strength) => isBoundedString(strength, 500)) ||
    !Array.isArray(eligibilityRequirements) ||
    eligibilityRequirements.length > 25 ||
    !Array.isArray(scoreDrivers) ||
    scoreDrivers.length > 6 ||
    !Array.isArray(risks) ||
    risks.length > 8 ||
    !Array.isArray(clarifications) ||
    clarifications.length > 8
  ) throw new Error('invalid response');

  const sourceRequirements = Array.isArray(tender.requirements) ? tender.requirements : [];
